//! macOS virtual key codes (`NSEvent.keyCode`, the `kVK_*` constants) to Linux
//! evdev key codes, which Wayland's `wl_keyboard.key` carries (xkb keycodes are
//! these plus 8).
//!
//! Generated by composing mitsuami-core's `MAC` and `EVDEV` tables
//! (`~/work/rust-ui-toolkit`, MIT OR Apache-2.0): each Mac code's key, then
//! that key's evdev code. Keys macOS reports but evdev has no code for are
//! left out.

/// The evdev code for a macOS virtual key code, if the key has one.
pub fn mac_to_evdev(code: u16) -> Option<u32> {
    let evdev = match code {
        0x00 => 30, // KeyA
        0x01 => 31, // KeyS
        0x02 => 32, // KeyD
        0x03 => 33, // KeyF
        0x04 => 35, // KeyH
        0x05 => 34, // KeyG
        0x06 => 44, // KeyZ
        0x07 => 45, // KeyX
        0x08 => 46, // KeyC
        0x09 => 47, // KeyV
        0x0a => 86, // IntlBackslash
        0x0b => 48, // KeyB
        0x0c => 16, // KeyQ
        0x0d => 17, // KeyW
        0x0e => 18, // KeyE
        0x0f => 19, // KeyR
        0x10 => 21, // KeyY
        0x11 => 20, // KeyT
        0x12 => 2, // Digit1
        0x13 => 3, // Digit2
        0x14 => 4, // Digit3
        0x15 => 5, // Digit4
        0x16 => 7, // Digit6
        0x17 => 6, // Digit5
        0x18 => 13, // Equal
        0x19 => 10, // Digit9
        0x1a => 8, // Digit7
        0x1b => 12, // Minus
        0x1c => 9, // Digit8
        0x1d => 11, // Digit0
        0x1e => 27, // BracketRight
        0x1f => 24, // KeyO
        0x20 => 22, // KeyU
        0x21 => 26, // BracketLeft
        0x22 => 23, // KeyI
        0x23 => 25, // KeyP
        0x24 => 28, // Enter
        0x25 => 38, // KeyL
        0x26 => 36, // KeyJ
        0x27 => 40, // Quote
        0x28 => 37, // KeyK
        0x29 => 39, // Semicolon
        0x2a => 43, // Backslash
        0x2b => 51, // Comma
        0x2c => 53, // Slash
        0x2d => 49, // KeyN
        0x2e => 50, // KeyM
        0x2f => 52, // Period
        0x30 => 15, // Tab
        0x31 => 57, // Space
        0x32 => 41, // Backquote
        0x33 => 14, // Backspace
        0x35 => 1, // Escape
        0x36 => 126, // MetaRight
        0x37 => 125, // MetaLeft
        0x38 => 42, // ShiftLeft
        0x39 => 58, // CapsLock
        0x3a => 56, // AltLeft
        0x3b => 29, // ControlLeft
        0x3c => 54, // ShiftRight
        0x3d => 100, // AltRight
        0x3e => 97, // ControlRight
        0x40 => 187, // F17
        0x41 => 83, // NumpadDecimal
        0x43 => 55, // NumpadMultiply
        0x45 => 78, // NumpadAdd
        0x47 => 69, // NumLock
        0x4b => 98, // NumpadDivide
        0x4c => 96, // NumpadEnter
        0x4e => 74, // NumpadSubtract
        0x4f => 188, // F18
        0x50 => 189, // F19
        0x51 => 117, // NumpadEqual
        0x52 => 82, // Numpad0
        0x53 => 79, // Numpad1
        0x54 => 80, // Numpad2
        0x55 => 81, // Numpad3
        0x56 => 75, // Numpad4
        0x57 => 76, // Numpad5
        0x58 => 77, // Numpad6
        0x59 => 71, // Numpad7
        0x5a => 190, // F20
        0x5b => 72, // Numpad8
        0x5c => 73, // Numpad9
        0x5d => 124, // IntlYen
        0x5e => 89, // IntlRo
        0x5f => 95, // NumpadComma
        0x60 => 63, // F5
        0x61 => 64, // F6
        0x62 => 65, // F7
        0x63 => 61, // F3
        0x64 => 66, // F8
        0x65 => 67, // F9
        0x66 => 123, // Lang2
        0x67 => 87, // F11
        0x68 => 122, // Lang1
        0x69 => 183, // F13
        0x6a => 186, // F16
        0x6b => 184, // F14
        0x6d => 68, // F10
        0x6e => 127, // ContextMenu
        0x6f => 88, // F12
        0x71 => 185, // F15
        0x72 => 110, // Insert
        0x73 => 102, // Home
        0x74 => 104, // PageUp
        0x75 => 111, // Delete
        0x76 => 62, // F4
        0x77 => 107, // End
        0x78 => 60, // F2
        0x79 => 109, // PageDown
        0x7a => 59, // F1
        0x7b => 105, // ArrowLeft
        0x7c => 106, // ArrowRight
        0x7d => 108, // ArrowDown
        0x7e => 103, // ArrowUp
        _ => return None,
    };
    Some(evdev)
}

#[cfg(test)]
mod tests {
    use super::mac_to_evdev;

    #[test]
    fn known_keys() {
        assert_eq!(mac_to_evdev(0x00), Some(30)); // A -> KEY_A
        assert_eq!(mac_to_evdev(0x37), Some(125)); // Command -> KEY_LEFTMETA
        assert_eq!(mac_to_evdev(0x3A), Some(56)); // Option -> KEY_LEFTALT
        assert_eq!(mac_to_evdev(0x3B), Some(29)); // Control -> KEY_LEFTCTRL
        assert_eq!(mac_to_evdev(0x7E), Some(103)); // Up -> KEY_UP
        assert_eq!(mac_to_evdev(0x3F), None); // fn: no evdev key here
    }
}
